// Compile-time polymorphism: method overloading
class PriceCalculator {
    // Same method name, different parameters
    public double calculatePrice(double amount) {
        return amount;
    }

    public double calculatePrice(double amount, double discount) {
        return amount - (amount * discount); // compiler picks this based on args
    }

    public double calculatePrice(double amount, double discount, double tax) {
        return (amount - (amount * discount)) * (1 + tax);
    }
}

// Runtime polymorphism: method overriding
abstract class PaymentMethod {
    abstract String processPayment(double amount);
}

class CreditCard extends PaymentMethod {
    String processPayment(double amount) { // overriding
        return "Charged $" + amount + " to credit card";
    }
}

class PayPal extends PaymentMethod {
    String processPayment(double amount) { // overriding
        return "Transferred $" + amount + " via PayPal";
    }
}

void checkout() {
    PaymentMethod payment = new CreditCard(); // parent reference, child object
    System.out.println(payment.processPayment(99.99)); // JVM decides at runtime which version runs
}
```

