class OrderService {
    // Valid: different number of parameters
    Order createOrder(Long customerId) {
        return createOrder(customerId, List.of(), 0.0);
    }

    Order createOrder(Long customerId, List<Product> products) {
        return createOrder(customerId, products, 0.0);
    }

    Order createOrder(Long customerId, List<Product> products, double discount) {
        return new Order(customerId, products, discount);
    }

    // Valid: different parameter types
    double calculateShipping(int zipCode) {
        return 5.99;
    }

    double calculateShipping(String address) { // different type = valid overload
        return 7.99;
    }

    // Valid: different parameter order
    void applyDiscount(String code, double amount) { }
    void applyDiscount(double amount, String code) { } // order matters

    // INVALID: same signature, different return type
    // double getTotal(Long orderId) { return 99.0; }
    // String getTotal(Long orderId) { return "99.0"; } // compile error!
}

void example() {
    var service = new OrderService();
    service.createOrder(123L); // compiler picks the 1-param version
    service.calculateShipping(10001); // int version called
    service.calculateShipping("123 Main St"); // String version called
}
