class Product {
    protected Product applyDiscount(double rate) throws Exception { // parent method
        return this;
    }

    public String getDescription() {
        return "Generic product";
    }
}

class DigitalProduct extends Product {
    @Override
    protected DigitalProduct applyDiscount(double rate) { // covariant return: DigitalProduct is subtype of Product
        return this; // valid: no checked exception thrown (narrower than parent)
    }

    @Override
    public String getDescription() { // valid: same access (public)
        return "Digital product with instant delivery";
    }

    // INVALID examples (commented to avoid compile errors):
    // private String getDescription() { } // error: weaker access, can't go public -> private

    // @Override
    // protected Product applyDiscount(int rate) { } // error: different parameter type, not overriding

    // @Override
    // protected Product applyDiscount(double rate) throws IOException { } // error: broader exception than parent
}

void main() {
    Product p = new DigitalProduct();
    p.applyDiscount(0.1); // runtime: calls DigitalProduct version
    System.out.println(p.getDescription()); // Output: Digital product with instant delivery
}
```
